DROP TABLE IF EXISTS `major_core_courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `major_core_courses` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `major_id` bigint NOT NULL COMMENT '专业ID',
  `course_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程名称',
  `course_english_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程英文名称',
  `course_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程代码',
  `course_description` text COLLATE utf8mb4_unicode_ci COMMENT '课程描述',
  `credits` int DEFAULT NULL COMMENT '学分',
  `course_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '必修' COMMENT '课程类型(必修/选修)',
  `semester` int DEFAULT NULL COMMENT '学期(第几学期)',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否已删除',
  PRIMARY KEY (`id`),
  KEY `idx_major_id` (`major_id`),
  KEY `idx_course_type` (`course_type`),
  KEY `idx_semester` (`semester`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_is_deleted` (`is_deleted`),
  CONSTRAINT `major_core_courses_ibfk_1` FOREIGN KEY (`major_id`) REFERENCES `school_programs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=304 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='专业核心课程表';
/*!40101 SET character_set_client = @saved_cs_client */;

