--
-- Table structure for table `messages`
--

DROP TABLE IF EXISTS `messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `messages` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `sender_id` bigint NOT NULL COMMENT '发送者ID',
  `sender_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发送者姓名',
  `sender_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'teacher' COMMENT '发送者类型(teacher/admin/system)',
  `receiver_id` bigint NOT NULL COMMENT '接收者ID',
  `application_id` bigint DEFAULT NULL COMMENT '关联申请ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息标题',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `message_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'notification' COMMENT '消息类型(notification/reminder/warning/info)',
  `priority` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal' COMMENT '优先级(high/normal/low)',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读(0-未读,1-已读)',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `requires_reply` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否需要回复(0-不需要,1-需要)',
  `reply_deadline` datetime DEFAULT NULL COMMENT '回复截止时间',
  `attachment_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件URL',
  `expires_at` datetime DEFAULT NULL COMMENT '消息过期时间',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '消息状态(active/archived/deleted)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_replied` bit(1) DEFAULT NULL,
  `read_at` datetime(6) DEFAULT NULL,
  `replied_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_receiver_id` (`receiver_id`),
  KEY `idx_sender_id` (`sender_id`),
  KEY `idx_application_id` (`application_id`),
  KEY `idx_message_type` (`message_type`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='消息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `messages`
--

