DROP TABLE IF EXISTS `rebates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rebates` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `student_id` bigint DEFAULT NULL COMMENT '关联的学生ID',
  `admission_id` bigint DEFAULT NULL COMMENT '关联的录取ID',
  `rebate_amount` double NOT NULL,
  `rebate_rate` decimal(5,2) DEFAULT NULL COMMENT '返点比例',
  `status` varchar(20) DEFAULT NULL COMMENT '返点状态(待审核/已审核/已发放等)',
  `payment_method` varchar(20) DEFAULT NULL COMMENT '支付方式(银行转账/支付宝/微信)',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '银行名称',
  `account_name` varchar(100) DEFAULT NULL COMMENT '账户名',
  `account_number` varchar(100) DEFAULT NULL COMMENT '账号',
  `digital_account` varchar(100) DEFAULT NULL COMMENT '数字支付账号(支付宝/微信)',
  `proof_file_path` varchar(255) DEFAULT NULL COMMENT '支付凭证文件路径',
  `agreement_accepted` tinyint(1) DEFAULT NULL COMMENT '是否同意返点协议',
  `agreement_date` timestamp NULL DEFAULT NULL COMMENT '同意协议时间',
  `review_status` varchar(20) DEFAULT NULL COMMENT '审核状态',
  `review_time` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `review_notes` text COMMENT '审核备注',
  `payment_status` varchar(20) DEFAULT NULL COMMENT '支付状态',
  `payment_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `payment_proof` varchar(255) DEFAULT NULL COMMENT '支付凭证',
  `notes` text COMMENT '备注',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `currency` varchar(10) DEFAULT NULL,
  `enrollment_id` bigint NOT NULL,
  `processed_date` datetime(6) DEFAULT NULL,
  `rebate_type` varchar(50) DEFAULT NULL,
  `request_date` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_rebates_student` (`student_id`),
  KEY `idx_rebates_admission` (`admission_id`),
  KEY `idx_rebates_status` (`status`),
  KEY `FK4qomaf0hou9ganqrg63eknjab` (`enrollment_id`),
  CONSTRAINT `FK4qomaf0hou9ganqrg63eknjab` FOREIGN KEY (`enrollment_id`) REFERENCES `enrollments` (`id`),
  CONSTRAINT `rebates_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `rebates_ibfk_2` FOREIGN KEY (`admission_id`) REFERENCES `admissions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='返点信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `rebates`
--

LOCK TABLES `rebates` WRITE;
/*!40000 ALTER TABLE `rebates` DISABLE KEYS */;
/*!40000 ALTER TABLE `rebates` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `school_faculties`
--

DROP TABLE IF EXISTS `school_faculties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `school_faculties` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学院ID',
  `school_id` bigint NOT NULL COMMENT '学校ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学院名称',
  `english_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学院英文名称',
  `code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学院代码',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '学院描述',
  `history` text COLLATE utf8mb4_unicode_ci COMMENT '学院历史',
  `ranking` int DEFAULT NULL COMMENT '学院排名',
  `dean_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '院长姓名',
  `faculty_count` int DEFAULT NULL COMMENT '教师数量',
  `student_count` int DEFAULT NULL COMMENT '学生数量',
  `website` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学院官网',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学院图片URL',
  `featured_programs` text COLLATE utf8mb4_unicode_ci COMMENT '特色专业',
  `research_areas` text COLLATE utf8mb4_unicode_ci COMMENT '研究领域',
  `contact_email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系邮箱',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `created_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除(0-未删除，1-已删除)',
  `status` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_school_id` (`school_id`),
  CONSTRAINT `fk_faculty_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `idx_school_id` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学校学院表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `school_faculties`
--

