--
-- Table structure for table `school_programs`
--

DROP TABLE IF EXISTS `school_programs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `school_programs` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '专业ID',
  `school_id` bigint NOT NULL COMMENT '学校ID',
  `faculty_id` bigint DEFAULT NULL COMMENT '学院ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '专业名称',
  `english_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业英文名称',
  `code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业代码',
  `degree_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学位类型(本科/硕士/博士)',
  `duration` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `language` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '英语' COMMENT '授课语言',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '专业描述',
  `curriculum` text COLLATE utf8mb4_unicode_ci COMMENT '课程设置',
  `career_prospects` text COLLATE utf8mb4_unicode_ci COMMENT '就业前景',
  `tuition_fee` decimal(38,2) DEFAULT NULL,
  `scholarship_available` tinyint(1) DEFAULT '0' COMMENT '是否提供奖学金',
  `rebate_percentage` int DEFAULT NULL,
  `application_deadline` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_date` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_popular` tinyint(1) DEFAULT '0' COMMENT '是否热门专业',
  `admission_requirements` text COLLATE utf8mb4_unicode_ci COMMENT '录取要求',
  `toefl_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ielts_requirement` double DEFAULT NULL,
  `gre_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gmat_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `work_experience_required` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credit_hours` int DEFAULT NULL COMMENT '学分要求',
  `thesis_required` tinyint(1) DEFAULT '0' COMMENT '是否需要论文',
  `internship_available` tinyint(1) DEFAULT '0' COMMENT '是否提供实习',
  `website` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业官网',
  `brochure_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业手册URL',
  `created_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除(0-未删除，1-已删除)',
  `status` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_faculty_id` (`faculty_id`),
  KEY `idx_degree_type` (`degree_type`),
  KEY `idx_is_popular` (`is_popular`),
  CONSTRAINT `fk_program_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `idx_faculty_id` FOREIGN KEY (`faculty_id`) REFERENCES `school_faculties` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=697 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学校专业表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `school_programs`
--

LOCK TABLES `school_programs` WRITE;
/*!40000 ALTER TABLE `school_programs` DISABLE KEYS */;
INSERT INTO `school_programs` VALUES (4,2,10,'人工智能','Artificial Intelligence','AI','硕士','2年','英语','斯坦福大学人工智能硕士项目是全球最顶尖的AI教育项目之一，提供从理论到应用的全面训练，培养能够推动AI技术发展和应用的领军人才。','课程覆盖机器学习、深度学习、计算机视觉、自然语言处理、机器人学和AI伦理等领域。学生需要完成核心课程、专业方向课程和一个毕业项目或论文。项目强调动手实践和研究参与。','毕业生在科技巨头、AI创业公司、研究实验室和学术机构拥有出色的就业前景，可担任AI研究科学家、机器学习工程师、数据科学家、算法专家等职位。',60000.00,1,10,'12月1日','9月上旬',1,'申请者需要计算机科学或相关领域的本科学位，强大的数学背景（线性代数、微积分、概率统计），编程经验和优秀的GRE成绩。研究经验是加分项。 奖学金信息：学校提供多种奖学金项目，包括学术优秀奖学金（£5,000-£15,000）、国际学生奖学金（£3,000-£10,000）、研究生助学金（£2,000-£8,000）、困难补助（£1,000-£5,000）等。申请截止日期通常为入学前一年的12月至次年3月。申请材料包括：完整的申请表、学术成绩单、推荐信、个人陈述、语言成绩证明、研究计划（研究生）等。建议提前准备并在截止日期前提交完整材料。','100',7,'320+','不要求','建议1-2年',45,1,1,'https://www.stanforduniversity.edu/artificial-intelligence/masters','https://www.stanforduniversity.edu/brochures/artificial-intelligence-硕士-brochure.pdf','2025-04-16 08:43:00','2025-10-20 17:55:56',0,1),(5,2,11,'工商管理','Master of Business Administration','MBA','硕士','2年','英语','斯坦福MBA项目以创新和创业精神闻名，培养具有变革思维和社会责任感的未来商业领袖。项目注重个人发展、领导力培养和实际问题解决能力。','第一年学习核心课程，建立商业基础知识。第二年学生可以根据兴趣选择专业领域深入学习，同时参与实践项目。课程设计强调跨学科学习和实际商业挑战的应对。','斯坦福MBA毕业生在创业、风险投资、科技、咨询和金融领域表现突出。许多毕业生创办自己的公司或加入高增长的科技企业，也有人进入管理咨询或投资银行。',74000.00,1,13,'1月5日','9月上旬',1,'申请要求包括本科学位、平均工作经验4年、GMAT或GRE成绩优秀、个人陈述、推荐信和面试。斯坦福特别重视申请者的个人素质和领导潜力。 奖学金信息：学校提供多种奖学金项目，包括学术优秀奖学金（£5,000-£15,000）、国际学生奖学金（£3,000-£10,000）、研究生助学金（£2,000-£8,000）、困难补助（£1,000-£5,000）等。申请截止日期通常为入学前一年的12月至次年3月。申请材料包括：完整的申请表、学术成绩单、推荐信、个人陈述、语言成绩证明、研究计划（研究生）等。建议提前准备并在截止日期前提交完整材料。','100',7,'不要求','720+','3-5年',60,0,1,'https://www.stanforduniversity.edu/master-of-business-administration/masters','https://www.stanforduniversity.edu/brochures/master-of-business-administration-硕士-brochure.pdf','2025-04-16 08:43:00','2025-10-20 17:55:56',0,1),(6,2,12,'医学博士','Doctor of Medicine','MD','博士','4年','英语','斯坦福医学院MD项目致力于培养既具备扎实医学知识，又拥有创新精神和领导能力的医生。课程设置强调科学探索、临床实践和患者关怀的结合。','前两年主要学习基础医学科学和器官系统课程。后两年进行临床轮转和选修课程学习，学生可以根据自己的职业规划选择专业方向。项目鼓励学生参与研究并提供丰富的国际医疗服务机会。','毕业生在全美顶尖医院获得住院医师职位，多数进入内科、外科、儿科、神经科学等专科领域。许多人继续从事医学研究、公共卫生或医疗管理，成为医学领域的创新者和领导者。',65000.00,1,20,'10月1日','8月中旬',1,'申请者需要完成本科学位和医学院入学考试(MCAT)，必修课程包括生物学、化学、物理学和有机化学。临床或研究经验、社区服务和领导力经历也很重要。 奖学金信息：学校提供多种奖学金项目，包括学术优秀奖学金（£5,000-£15,000）、国际学生奖学金（£3,000-£10,000）、研究生助学金（£2,000-£8,000）、困难补助（£1,000-£5,000）等。申请截止日期通常为入学前一年的12月至次年3月。申请材料包括：完整的申请表、学术成绩单、推荐信、个人陈述、语言成绩证明、研究计划（研究生）等。建议提前准备并在截止日期前提交完整材料。','100',7,'不要求','不要求','建议有医疗相关经验',240,1,1,'https://www.stanforduniversity.edu/doctor-of-medicine/phd','https://www.stanforduniversity.edu/brochures/doctor-of-medicine-博士-brochure.pdf','2025-04-16 08:43:00','2025-10-20 17:55:56',0,1),(7,3,13,'哲学','Philosophy','PHIL','本科','3年','英语','牛津大学作为世界最古老、最负盛名的大学之一，该专业享有无与伦比的国际声誉和学术地位。学校拥有900多年的悠久历史和深厚的学术传统，为学生提供世界顶级的教育资源和研究环境。专业课程设计严谨，注重培养学生的批判性思维、独立研究能力和学术创新精神。牛津大学采用独特的导师制教学模式，为每位学生配备专门的导师进行一对一指导。学校与全球顶尖企业、政府机构和学术组织保持密切合作，为学生提供卓越的实习和职业发展机会。牛津大学的毕业生在各个领域都享有极高的声誉，是全球雇主最青睐的人才。','课程体系完善，包含核心必修课程、专业选修课程和实践教学环节。核心课程涵盖专业基础理论、研究方法、学术写作和批判性思维等内容。选修课程提供多元化的学习方向，学生可根据个人兴趣和职业规划进行选择。实践环节包括实验室学习、项目研究、实习实训、学术交流等，注重理论与实践相结合。教学方式灵活多样，采用讲座、研讨、案例分析、小组合作等形式，培养学生的独立思考能力和团队协作精神。课程设置与时俱进，紧跟行业发展趋势和学术前沿。','毕业生就业前景良好，受到用人单位的广泛认可。主要就业领域包括：企业管理、政府部门、教育机构、研究院所、金融机构、科技公司、咨询服务等。典型职位包括：专业技术人员、项目经理、研究助理、分析师、顾问、管理培训生等。毕业生起薪水平具有竞争力，随着工作经验的积累，薪资和职位都有良好的发展空间。学校提供完善的职业指导服务和校友网络支持，定期举办招聘会和职业发展讲座。大部分毕业生能够在毕业后较短时间内找到满意的工作，就业率保持在较高水平。',35000.00,1,10,'2024年1月15日','10月上旬',0,'申请者需要优秀的学术成绩，尤其是与哲学相关的科目如文学、历史或数学。申请过程包括提交个人陈述、学术论文样本，并参加牛津思维能力测试和面试。 奖学金信息：学校提供多种奖学金项目，包括学术优秀奖学金（£5,000-£15,000）、国际学生奖学金（£3,000-£10,000）、研究生助学金（£2,000-£8,000）、困难补助（£1,000-£5,000）等。申请截止日期通常为入学前一年的12月至次年3月。申请材料包括：完整的申请表、学术成绩单、推荐信、个人陈述、语言成绩证明、研究计划（研究生）等。建议提前准备并在截止日期前提交完整材料。','100分以上',7,'不要求','不要求','不要求',360,1,1,'https://www.universityofoxford.edu/philosophy/undergraduate','https://www.universityofoxford.edu/brochures/philosophy-本科-brochure.pdf','2025-04-16 08:43:00','2025-10-20 17:55:56',0,1),(9,4,15,'金融学','Finance','FIN','硕士','2年','英语','该专业隶属于享有国际声誉的知名大学，学校在相关领域具有深厚的学术底蕴和卓越的教学质量。专业课程设计紧跟时代发展，结合理论学习与实践应用，培养学生的专业技能和创新能力。学校拥有优秀的师资团队和先进的教学设施，为学生提供良好的学习环境和研究条件。专业注重培养学生的批判性思维、问题解决能力和国际视野，通过多样化的