DROP TABLE IF EXISTS `schools`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schools` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学校ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学校名称',
  `english_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '英文名称',
  `country` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所在国家',
  `country_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '国家代码(如us, uk, ca)',
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在城市',
  `state` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在州/省',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详细地址',
  `campus` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校区信息',
  `type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学校类型(综合大学/理工/文理等)',
  `ownership` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公立/私立',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '学校简介',
  `history` text COLLATE utf8mb4_unicode_ci COMMENT '学校历史',
  `features` text COLLATE utf8mb4_unicode_ci COMMENT '学校特色',
  `world_ranking` int DEFAULT NULL COMMENT '世界排名',
  `national_ranking` int DEFAULT NULL COMMENT '本国排名',
  `qs_ranking` int DEFAULT NULL COMMENT 'QS排名',
  `times_ranking` int DEFAULT NULL COMMENT '泰晤士排名',
  `shanghai_ranking` int DEFAULT NULL COMMENT '上海交大排名',
  `tuition_fee` decimal(10,2) DEFAULT NULL,
  `rebate_percentage` decimal(5,2) DEFAULT NULL COMMENT '返点比例(%)',
  `living_cost` decimal(12,2) DEFAULT NULL COMMENT '生活费估算(人民币/年)',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '货币单位',
  `international_student_percentage` decimal(5,2) DEFAULT NULL COMMENT '国际学生比例(%)',
  `chinese_student_count` int DEFAULT NULL COMMENT '中国学生数量',
  `total_student_count` int DEFAULT NULL COMMENT '学生总数',
  `student_faculty_ratio` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '师生比例',
  `acceptance_rate` decimal(5,2) DEFAULT NULL COMMENT '录取率(%)',
  `average_gpa` decimal(3,2) DEFAULT NULL COMMENT '平均录取GPA',
  `toefl_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'TOEFL要求',
  `ielts_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IELTS要求',
  `gre_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'GRE要求',
  `gmat_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'GMAT要求',
  `sat_requirement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SAT要求',
  `application_deadline` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请截止日期',
  `website` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '官方网站',
  `logo_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Logo图片URL',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学校图片URL',
  `banner_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '横幅图片URL',
  `has_undergraduate` tinyint(1) DEFAULT '1' COMMENT '是否提供本科教育',
  `has_graduate` tinyint(1) DEFAULT '1' COMMENT '是否提供研究生教育',
  `has_phd` tinyint(1) DEFAULT '1' COMMENT '是否提供博士教育',
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签(逗号分隔)',
  `student_services` text COLLATE utf8mb4_unicode_ci COMMENT '学生服务',
  `housing_info` text COLLATE utf8mb4_unicode_ci COMMENT '住宿信息',
  `famous_alumni` text COLLATE utf8mb4_unicode_ci COMMENT '著名校友',
  `notable_programs` text COLLATE utf8mb4_unicode_ci COMMENT '知名专业',
  `entry_requirement` text COLLATE utf8mb4_unicode_ci COMMENT '入学要求',
  `scholarship_info` text COLLATE utf8mb4_unicode_ci COMMENT '奖学金信息',
  `visa_info` text COLLATE utf8mb4_unicode_ci COMMENT '签证信息',
  `contact_email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系邮箱',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `created_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除(0-未删除，1-已删除)',
  `status` int DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `featured_programs` text COLLATE utf8mb4_unicode_ci,
  `fee_currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `the_ranking` int DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_name_country` (`name`,`country`),
  KEY `idx_country` (`country`),
  KEY `idx_world_ranking` (`world_ranking`),
  KEY `idx_tuition_fee` (`tuition_fee`),
  KEY `idx_rebate_percentage` (`rebate_percentage`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学校信息表';
