--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `students` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请编号',
  `user_id` bigint DEFAULT NULL,
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `english_name` varchar(50) DEFAULT NULL COMMENT '英文名',
  `gender` varchar(10) DEFAULT NULL COMMENT '性别',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `nationality` varchar(50) DEFAULT NULL COMMENT '国籍',
  `passport_no` varchar(50) DEFAULT NULL COMMENT '护照号',
  `phone` varchar(20) DEFAULT NULL COMMENT '电话',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `wechat` varchar(50) DEFAULT NULL COMMENT '微信',
  `current_school` varchar(100) DEFAULT NULL COMMENT '当前就读学校',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `gpa` decimal(3,2) DEFAULT NULL COMMENT 'GPA成绩',
  `gpa_scale` varchar(10) DEFAULT NULL COMMENT 'GPA制度(4.0/5.0等)',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `toefl` decimal(5,1) DEFAULT NULL COMMENT '托福成绩',
  `ielts` decimal(3,1) DEFAULT NULL COMMENT '雅思成绩',
  `gre` int DEFAULT NULL COMMENT 'GRE成绩',
  `gmat` int DEFAULT NULL COMMENT 'GMAT成绩',
  `application_status` varchar(20) DEFAULT 'pending' COMMENT '申请状态(待处理/处理中/已提交等)',
  `application_progress` int DEFAULT '0' COMMENT '申请进度(百分比)',
  `current_step` int DEFAULT '1' COMMENT '当前申请步骤(1-6)',
  `target_countries` varchar(200) DEFAULT NULL COMMENT '目标申请国家',
  `advisor_id` bigint DEFAULT NULL COMMENT '负责的顾问ID',
  `notes` text COMMENT '申请备注',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_application_status` (`application_status`),
  KEY `idx_advisor_id` (`advisor_id`),
  CONSTRAINT `fk_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=123162 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生基本信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

