--
-- Table structure for table `sys_log`
--

DROP TABLE IF EXISTS `sys_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_log` (
  `oper_id` bigint NOT NULL AUTO_INCREMENT,
  `action_type` varchar(50) DEFAULT NULL,
  `error_msg` text,
  `json_result` text,
  `method` varchar(255) DEFAULT NULL,
  `oper_ip` varchar(128) DEFAULT NULL,
  `oper_location` varchar(255) DEFAULT NULL,
  `oper_name` varchar(50) DEFAULT NULL,
  `oper_param` text,
  `oper_time` datetime(6) DEFAULT NULL,
  `oper_type` varchar(2) DEFAULT NULL,
  `oper_url` varchar(255) DEFAULT NULL,
  `oper_user_id` bigint DEFAULT NULL,
  `page_module` varchar(100) DEFAULT NULL,
  `status` varchar(1) DEFAULT NULL,
  `student_id` bigint DEFAULT NULL,
  `student_name` varchar(100) DEFAULT NULL,
  `title` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`oper_id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

